// Some portions generated by Claude
import { GRAPH_HEIGHT, GRAPH_WIDTH } from "./graph-config.ts";
import type { GraphBox, GraphTransform, PointerPosition } from "./graph-types.ts";
export type ViewportPoint = {
  x: number;
  y: number;
};

export type ViewportTransform = {
  x: number;
  y: number;
  k: number;
};

export type ViewportRect = {
  left: number;
  top: number;
  width: number;
  height: number;
};

/**
 * Convert a client coordinate to viewBox space without allowing a transient
 * zero-sized responsive canvas to introduce Infinity or NaN into the graph
 * transform.
 */
export function clientPointToViewport(
  clientX: number,
  clientY: number,
  rect: ViewportRect,
  viewport: { width: number; height: number },
): ViewportPoint {
  const width =
    Number.isFinite(rect.width) && rect.width > 0 ? rect.width : viewport.width;
  const height =
    Number.isFinite(rect.height) && rect.height > 0
      ? rect.height
      : viewport.height;
  const scale = Math.min(width / viewport.width, height / viewport.height);
  return {
    x: (clientX - rect.left - (width - viewport.width * scale) / 2) / scale,
    y: (clientY - rect.top - (height - viewport.height * scale) / 2) / scale,
  };
}

export const MIN_GRAPH_ZOOM = 0.001;
export const MAX_GRAPH_ZOOM = 8;

export function zoomTransformAt(
  current: ViewportTransform,
  factor: number,
  focalPoint: ViewportPoint,
  minimum = MIN_GRAPH_ZOOM,
  maximum = MAX_GRAPH_ZOOM,
): ViewportTransform {
  if (!Number.isFinite(factor) || factor <= 0) return current;
  const nextK = Math.max(minimum, Math.min(maximum, current.k * factor));
  const ratio = nextK / current.k;
  return {
    k: nextK,
    x: focalPoint.x - (focalPoint.x - current.x) * ratio,
    y: focalPoint.y - (focalPoint.y - current.y) * ratio,
  };
}

export function panTransformBy(
  current: ViewportTransform,
  delta: ViewportPoint,
): ViewportTransform {
  return {
    ...current,
    x: current.x + delta.x,
    y: current.y + delta.y,
  };
}

export function centerTransformOn(
  point: ViewportPoint,
  scale: number,
  viewport: { width: number; height: number },
): ViewportTransform {
  return {
    x: viewport.width / 2 - point.x * scale,
    y: viewport.height / 2 - point.y * scale,
    k: scale,
  };
}

/** Scale around the old midpoint, then move that anchor to the new midpoint. */
export function pinchPanTransform(
  current: ViewportTransform,
  previous: { distance: number; midpoint: ViewportPoint },
  next: { distance: number; midpoint: ViewportPoint },
  minimum = MIN_GRAPH_ZOOM,
): ViewportTransform {
  const factor =
    previous.distance > 0 && next.distance > 0
      ? next.distance / previous.distance
      : 1;
  return panTransformBy(
    zoomTransformAt(current, factor, previous.midpoint, minimum),
    {
      x: next.midpoint.x - previous.midpoint.x,
      y: next.midpoint.y - previous.midpoint.y,
    },
  );
}

type NavigatorLike = { platform?: string; userAgent?: string; userAgentData?: { platform?: string } };

/**
 * Macs, iPhones and iPads: their trackpads scroll with two fingers and zoom with a pinch, so the wheel pans the graph.
 * Elsewhere a wheel is most often a mouse wheel, and it zooms.
 */
export function isApplePlatform(nav: NavigatorLike | undefined = typeof navigator === "undefined" ? undefined : navigator) {
  const platform = nav?.userAgentData?.platform || nav?.platform || nav?.userAgent || "";
  return /mac|iphone|ipad|ipod/i.test(platform);
}

/**
 * Browsers deliver trackpad pinch as Ctrl-wheel, and it always zooms. An ordinary wheel pans (two-finger scrolling on
 * a Mac) or, with `wheelZooms`, zooms about the cursor (a mouse wheel on Windows and Linux).
 */
export function wheelTransform(
  current: ViewportTransform,
  event: {
    deltaX: number;
    deltaY: number;
    deltaMode: number;
    ctrlKey?: boolean;
    metaKey?: boolean;
    shiftKey?: boolean;
  },
  focalPoint: ViewportPoint,
  screenScale = 1,
  minimum = MIN_GRAPH_ZOOM,
  { wheelZooms = false }: { wheelZooms?: boolean } = {},
): ViewportTransform {
  const unit = event.deltaMode === 1 ? 16 : event.deltaMode === 2 ? 780 : 1;
  const dx = Number.isFinite(event.deltaX) ? event.deltaX * unit : 0;
  const dy = Number.isFinite(event.deltaY) ? event.deltaY * unit : 0;
  if (event.ctrlKey || event.metaKey)
    return zoomTransformAt(
      current,
      Math.exp(-Math.max(-200, Math.min(200, dy)) * 0.003),
      focalPoint,
      minimum,
    );
  if (wheelZooms)
    // Shift-wheel arrives as a horizontal delta on Windows.
    return zoomTransformAt(
      current,
      Math.exp(-Math.max(-300, Math.min(300, dy || dx)) * 0.002),
      focalPoint,
      minimum,
    );
  const scale =
    Number.isFinite(screenScale) && screenScale > 0 ? screenScale : 1;
  return panTransformBy(current, {
    x: -(event.shiftKey && !dx ? dy : dx) / scale,
    y: event.shiftKey && !dx ? 0 : -dy / scale,
  });
}

export const MAX_INCREMENTAL_ZOOM_OUT = 0.88;

export function revealBoxesIncrementally(
  current: GraphTransform,
  startAnchor: PointerPosition,
  targetAnchor: PointerPosition,
  boxes: GraphBox[],
  // Viewport units covered on the right, by the details card.
  rightInset = 0,
) {
  if (!boxes.length) return current;
  const padding = 58;
  const right = GRAPH_WIDTH - padding - rightInset;
  const minX = Math.min(...boxes.map((box) => box.x - box.width / 2));
  const maxX = Math.max(...boxes.map((box) => box.x + box.width / 2));
  const minY = Math.min(...boxes.map((box) => box.y - box.height / 2));
  const maxY = Math.max(...boxes.map((box) => box.y + box.height / 2));
  const fitScale = Math.min(
    current.k,
    (right - padding) / Math.max(1, maxX - minX),
    (GRAPH_HEIGHT - padding * 2) / Math.max(1, maxY - minY),
  );
  const k = Math.min(
    current.k,
    Math.max(current.k * MAX_INCREMENTAL_ZOOM_OUT, fitScale),
  );
  const anchorScreen = {
    x: current.x + startAnchor.x * current.k,
    y: current.y + startAnchor.y * current.k,
  };
  let x = anchorScreen.x - targetAnchor.x * k;
  let y = anchorScreen.y - targetAnchor.y * k;
  const screenBounds = () => ({
    left: x + minX * k,
    right: x + maxX * k,
    top: y + minY * k,
    bottom: y + maxY * k,
  });
  let bounds = screenBounds();
  if (bounds.right - bounds.left > right - padding) {
    x = (padding + right) / 2 - ((minX + maxX) / 2) * k;
  } else if (bounds.left < padding) {
    x += padding - bounds.left;
  } else if (bounds.right > right) {
    x -= bounds.right - right;
  }
  bounds = screenBounds();
  if (bounds.bottom - bounds.top > GRAPH_HEIGHT - padding * 2) {
    y = GRAPH_HEIGHT / 2 - ((minY + maxY) / 2) * k;
  } else if (bounds.top < padding) {
    y += padding - bounds.top;
  } else if (bounds.bottom > GRAPH_HEIGHT - padding) {
    y -= bounds.bottom - (GRAPH_HEIGHT - padding);
  }
  return { x, y, k };
}

type Rect = { left: number; top: number; width: number; height: number };

/**
 * The part of the canvas a person can see, in view-box units: the canvas element (whose view box is scaled to fit and
 * letterboxed) minus a card over it, a card on the right or (as on phones) a sheet along the bottom.
 */
export function visibleArea(svg: Rect, card: Rect | null, viewport: { width: number; height: number }) {
  const scale = Math.min(svg.width / viewport.width, svg.height / viewport.height) || 1;
  const letterboxX = (svg.width / scale - viewport.width) / 2;
  const letterboxY = (svg.height / scale - viewport.height) / 2;
  const area = { left: 0 - letterboxX || 0, top: 0 - letterboxY || 0, right: viewport.width + letterboxX, bottom: viewport.height + letterboxY };
  if (!card || !card.width || !card.height) return area;
  if (card.width >= svg.width * 0.8) area.bottom = Math.min(area.bottom, (card.top - svg.top) / scale - letterboxY);
  else area.right = Math.min(area.right, (card.left - svg.left) / scale - letterboxX - 12);
  return area;
}

/**
 * The transform that brings a point (graph units) to the middle of the visible area at the current zoom, or null
 * when it is already at least `margin` inside it.
 */
export function revealPoint(
  point: ViewportPoint,
  current: ViewportTransform,
  area: { left: number; top: number; right: number; bottom: number },
  margin = 60,
): ViewportTransform | null {
  const x = current.x + point.x * current.k;
  const y = current.y + point.y * current.k;
  if (x >= area.left + margin && x <= area.right - margin && y >= area.top + margin && y <= area.bottom - margin) return null;
  return {
    x: (area.left + area.right) / 2 - point.x * current.k,
    y: (area.top + area.bottom) / 2 - point.y * current.k,
    k: current.k,
  };
}
